import {escape as esc, icon, mark, badge, bytes, empty, action, panel} from './prism-ui.js';
import {mountGlobe} from './u1-globe.js';
import {autopilotView} from './u1-autopilot.js';
import './u1-experience.js';
import './u1-media.js';
import './u1-global-controls.js';
import './u1-live-motion.js';
import './u1-terminal.js';

const stylesheet=document.createElement('link');stylesheet.rel='stylesheet';stylesheet.href='/css/prism-os.css';document.head.appendChild(stylesheet);
const identity=document.createElement('link');identity.rel='stylesheet';identity.href='/css/u1-reference.css';document.head.appendChild(identity);
const font=document.createElement('link');font.rel='stylesheet';font.href='https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Manrope:wght@400;500;600;700&display=swap';document.head.appendChild(font);
document.documentElement.classList.add('prism-theme');
const viewport=document.getElementById('stageViewport');
if(viewport) startDesktop(viewport); else skinStandalone();

function skinStandalone(){
  document.body.classList.add('prism-standalone');document.title=document.title.replace(/U1 OS/g,'U1 OS');
  const brand=document.querySelector('.studio-brand');if(brand)brand.innerHTML=`<span class="prism-logo">${mark()}</span><span>U1 OS<small>YOUR WORLD. AMPLIFIED.</small></span>`;
  const top=document.querySelector('.studio-topbar');if(top){const label=top.querySelector('.breadcrumb a');if(label)label.textContent='U1 OS';}
}

function startDesktop(legacyViewport){
  if(document.getElementById('prism-shell'))return;
  const NAV=[['home','Home','home'],['ai','AI Command','ai'],['projects','Projects','projects'],['files','Files & Drive','files'],['integrations','Integrations','integrations'],['calendar','Calendar','calendar'],['tasks','Tasks','tasks'],['notes','Notes','notes'],['media','Media','media'],['automation','Automation','automation'],['system','System','system'],['settings','Settings','settings']];
  const providers=[['codex','ChatGPT / Codex','Research · Code · Create'],['claude','Claude','Analyse · Plan · Write'],['antigravity','Antigravity','Build · Deploy · Automate'],['canva','Canva','Design · Visualise · Present']];
  const extras=[['assistant','AI assistant','ai'],['ai','AI workbench','code'],['tools','Tool library','projects'],['osint','Research casebook','search'],['sports','Live sports','globe'],['comms','Email & calendar tools','mail'],['finance','Finance','projects'],['crypto','Crypto desk','automation'],['deploy','Deployment workspace','code'],['gaming','Game development','media'],['studio','Video studio','media'],['finder','Auto Finder','automation'],['settings','Advanced system settings','settings']];
  let state={view:'home',profile:{name:'Andrew',city:'Beveridge, Victoria',country:'AU',timezone:'Australia/Melbourne',effects:'balanced',focus:false,contrast:false,drive_plan_tb:5},records:[],files:[],folders:[],storage:null,catalog:[],runtime:{},usage:null,system:null,weather:null,notifications:[],connected:false,loaded:false};
  let csrf='',summaryBusy=false,systemBusy=false,weatherBusy=false,disposeGlobe=()=>{},toastTimer,searchSelection=0,searchItems=[],returnFocus=null,modalSubmit=null,mediaUrl=null;
  let month=new Date().toISOString().slice(0,7),fileFilter='',taskFilter='all',history=[],pendingUploads=false;
  let autopilot=null;
  const shell=document.createElement('div');shell.id='prism-shell';shell.innerHTML=`
    <aside class="prism-sidebar" aria-label="U1 navigation"><a class="prism-brand" href="#home"><span class="prism-logo">${mark()}</span><span>U1 OS<small>YOUR WORLD. AMPLIFIED.</small></span></a><nav aria-label="Main navigation">${NAV.map(([key,name,glyph])=>`<button type="button" data-route="${key}" title="${name}">${icon(glyph)}<span>${name}</span><i data-count="${key}"></i></button>`).join('')}</nav><button type="button" class="prism-library-link" data-route="apps">${icon('plus')}<span>App library</span></button><div class="prism-sidebar-quote"><span>YOUR NEXT CHAPTER</span><p>A brighter tomorrow<br>starts with what<br>you create today.</p><i></i></div><span class="prism-local-status" id="prism-connection-label">Connecting to local workspace</span></aside>
    <div class="prism-main"><header class="prism-topbar"><button type="button" class="prism-icon-button prism-mobile-menu" id="prism-menu" aria-label="Toggle navigation" aria-expanded="false">${icon('menu')}</button><button type="button" class="prism-global-search" id="prism-search-button">${icon('search')}<span>Search your world...</span><kbd>⌘ K</kbd></button><div class="prism-top-actions"><button type="button" class="prism-icon-button" id="prism-notifications" aria-label="Notifications">${icon('bell')}<span id="prism-notification-count" hidden></span></button><button type="button" class="prism-profile" data-route="settings">${icon('user')}<span id="prism-user-name">Andrew</span><small>⌄</small></button><button type="button" class="prism-icon-button" data-route="settings" aria-label="Quick settings">${icon('settings')}</button></div><span class="prism-focus-caption" id="prism-focus-caption">FOCUS · CREATE · AUTOMATE · ACHIEVE</span></header>
    <div id="prism-live-bar" aria-label="Existing live feeds"></div><main id="prism-scroll"><div id="prism-page" tabindex="-1"></div><div id="prism-legacy" hidden></div><footer class="prism-footer"><span>HUMAN IDEAS <b>+</b> AI POWER <b>=</b> A BRIGHTER TOMORROW</span><button type="button" data-route="settings">U1 OS / LOCAL WORKSPACE</button></footer></main></div>
    <nav class="prism-dock" aria-label="Quick action dock">${[['ai','AI','ai'],['legacy:ai','Code','code'],['studio','Design','ai'],['files','Files','files']].map(([route,label,glyph])=>dockItem(route,label,glyph)).join('')}<button type="button" class="prism-dock-core" data-route="ai" aria-label="Open U1 AI Command">${mark()}<i></i></button>${[['web','Web','globe'],['notes','Notes','notes'],['media','Media','media'],['settings','Settings','settings']].map(([route,label,glyph])=>dockItem(route,label,glyph)).join('')}</nav>
    <dialog id="prism-search-dialog" class="prism-dialog prism-search-dialog" aria-labelledby="prism-search-title"><header><div><small>YOUR WORLD, WITHIN REACH</small><h2 id="prism-search-title">What are you looking for?</h2></div><button type="button" class="prism-icon-button" data-close-search aria-label="Close search">${icon('close')}</button></header><label class="prism-search-input">${icon('search')}<input id="prism-search-input" type="search" placeholder="Projects, notes, tasks, files, apps..." autocomplete="off" aria-label="Search your workspace"></label><ul id="prism-search-results"></ul><footer>↑ ↓ to choose · Enter to open · Esc to close<span>Cloud file search requires an authorized connector.</span></footer></dialog>
    <dialog id="prism-modal" class="prism-dialog" aria-labelledby="prism-modal-title"><header><div><small id="prism-modal-eyebrow">U1 WORKSPACE</small><h2 id="prism-modal-title"></h2></div><button type="button" class="prism-icon-button" data-close-modal aria-label="Close dialog">${icon('close')}</button></header><div id="prism-modal-content"></div></dialog><div id="prism-toast" role="status" aria-live="polite" hidden></div><input type="file" id="prism-file-input" multiple hidden>`;
  document.body.appendChild(shell);document.body.classList.add('prism-active');
  const $=id=>document.getElementById(id),page=$('prism-page'),modal=$('prism-modal'),searchDialog=$('prism-search-dialog'),searchInput=$('prism-search-input');
  $('prism-legacy').appendChild(legacyViewport);
  const live=document.querySelector('[aria-label="Live information bar"]');if(live)$('prism-live-bar').appendChild(live);else $('prism-live-bar').hidden=true;
  const items=kind=>state.records.filter(record=>record.kind===kind);
  const readyFiles=()=>state.files.filter(file=>file.status==='ready');
  function dockItem(route,label,glyph){return `<button type="button" data-route="${route}" title="${label}">${icon(glyph)}<span>${label}</span></button>`;}
  function notice(message,error=false){const el=$('prism-toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},error?7500:4300);}
  function safeError(error){const text=String(error?.message||'');return /Traceback|ReferenceError|TypeError|<html|stack/i.test(text)?'That service is unavailable. Your existing data has not been replaced.':text.slice(0,240)||'The action could not be completed. Please try again.';}
  async function catalog(){const response=await fetch('/api/integrations',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error('Account setup is temporarily unavailable.');const data=await response.json();csrf=data.csrf_token||'';state.catalog=Array.isArray(data.cards)?data.cards:[];state.runtime=data.runtime||{};return data;}
  async function api(path,body,again=false){const post=body!==undefined;if(post&&!csrf)await catalog();const options={signal:AbortSignal.timeout(path.includes('/file?')?45000:24000),headers:{'Accept':'application/json'}};if(post){options.method='POST';options.headers['Content-Type']='application/json';options.headers['X-U1-CSRF']=csrf;options.body=JSON.stringify(body);if(new TextEncoder().encode(options.body).length>62000)throw new Error('This item is too long to save in one request. Please shorten the text.');}const response=await fetch(path,options);if(response.status===403&&post&&!again){await catalog();return api(path,body,true);}let data;try{data=await response.json();}catch(_){throw new Error('The local service did not return a usable response.');}if(!response.ok||data.success===false)throw new Error(data.error||'This service is not ready. Check its setup and try again.');return data;}
  const endpoint=action=>`/api/workspace/prism/${action}`;
  function timeLabel(value,options={day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}){const date=new Date(typeof value==='number'?value*1000:value);return Number.isFinite(date.getTime())?date.toLocaleString('en-AU',{timeZone:state.profile.timezone,...options}):'Unavailable';}
  function dayKey(date=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:state.profile.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);return ['year','month','day'].map(type=>parts.find(p=>p.type===type).value).join('-');}
  function applyPreferences(){document.documentElement.dataset.prismEffects=state.profile.effects;document.documentElement.classList.toggle('prism-high-contrast',state.profile.contrast);shell.classList.toggle('prism-focus',state.profile.focus);$('prism-user-name').textContent=state.profile.name;$('prism-focus-caption').textContent=state.profile.focus?'FOCUS MODE · A LITTLE LESS NOISE':'FOCUS · CREATE · AUTOMATE · ACHIEVE';}
  function header(eyebrow,title,description,buttons=''){return `<header class="prism-page-header"><div><p>${esc(eyebrow)}</p><h1>${esc(title)}</h1><span>${esc(description)}</span></div><div>${buttons}</div></header>`;}
  function newButton(kind,label){return `<button type="button" class="prism-button primary" data-new="${kind}">${icon('plus')}${esc(label)}</button>`;}
  function statusTag(text,style='neutral'){return `<span class="prism-status ${style}">${esc(text)}</span>`;}
  function providerStatus(id){if(id==='codex'){const provider=state.usage?.providers?.codex;if(provider?.success&&!provider.stale)return {text:'CLI readable',style:'success'};return {text:'Check connection',style:'neutral'};}const card=state.catalog.find(c=>c.id===(id==='claude'?'anthropic':id));return card?.saved_fields?{text:'Authorization unverified',style:'warning'}:{text:'Needs setup',style:'neutral'};}
  function providerCards(){return `<div class="prism-provider-grid">${providers.map(([id,name,purpose])=>{const status=providerStatus(id);return `<button type="button" class="prism-provider ${id}" data-provider="${id}">${badge(id)}<strong>${name}</strong><span>${purpose}</span>${statusTag(status.text,status.style)}<i class="prism-provider-energy" aria-hidden="true"></i></button>`;}).join('')}<button type="button" class="prism-add-tool" data-route="integrations">${icon('plus')}<span>Add tool</span></button></div>`;}
  function projectRows(){const projects=items('project');if(projects.length)return `<div class="prism-project-rows">${projects.slice(0,4).map(project=>`<button type="button" class="prism-project-row" data-edit="${project.id}"><span class="prism-row-icon">${icon('projects')}</span><span><strong>${esc(project.title)}</strong><small>${esc(project.payload.category)} · ${esc(project.payload.status)}</small></span><span class="prism-progress-wrap">${Number.isFinite(project.payload.progress)?`<progress max="100" value="${project.payload.progress}" aria-label="User-reported progress"></progress><small>${project.payload.progress}%</small>`:'<small>Not measured</small>'}</span></button>`).join('')}</div>`;if(state.folders.length)return `<div class="prism-project-rows">${state.folders.slice(0,4).map((folder,index)=>`<button type="button" class="prism-project-row" data-folder="${index}"><span class="prism-row-icon">${icon('projects')}</span><span><strong>${esc(folder.name)}</strong><small>${folder.current?'This workspace':'Local folder'} · Progress not tracked</small></span>${icon('arrow')}</button>`).join('')}</div>`;return empty(state.loaded?'Your next project starts here':'Loading your workspace...',state.loaded?'Create a project to track real work and your own progress.':'Waiting for the local project database.',newButton('project','New project'));}
  function gauge(label,value){return `<div class="prism-gauge"><div style="--gauge:${Number.isFinite(value)?Math.max(0,Math.min(100,value))*3.6:0}deg"><span>${label}<strong>${Number.isFinite(value)?`${Math.round(value)}%`:'--'}</strong></span></div><small>${Number.isFinite(value)?'Measured':'Unavailable'}</small></div>`;}
  function systemBody(){const data=state.system;const values=history.filter(p=>Number.isFinite(p.cpu));let chart='<span class="prism-chart-empty">Collecting measured history...</span>';if(values.length>1){const points=values.map((v,i)=>`${i/(values.length-1)*280},${66-v.cpu*.56}`).join(' ');chart=`<svg viewBox="0 0 280 76" role="img" aria-label="Measured CPU history"><path d="M0 20H280M0 45H280M0 70H280" stroke="#2b4760" stroke-width=".5"/><polyline points="${points}" fill="none" stroke="#54deff" stroke-width="1.5"/></svg>`;}return `<div class="prism-gauges">${gauge('CPU',data?.cpu)}${gauge('GPU',data?.gpu)}${gauge('RAM',data?.memory?.percent)}${gauge('DISK',data?.disk?.percent)}</div><div class="prism-metric-history">${chart}</div><p class="prism-source">${data?`${esc(data.source)} · ${timeLabel(data.sampled_at,{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`:'Waiting for local telemetry. Unavailable values are not estimated.'}</p>`;}
  function driveBody(){return `<div class="prism-drive-title">${badge('google_drive')}<div><strong>Google Drive</strong><span>5 TB plan · user-reported</span></div></div><div class="prism-drive-unavailable"><span>USAGE & AVAILABLE CAPACITY</span><strong>Authorization required</strong><p>No cloud usage or files are assumed from a browser login.</p></div><div class="prism-folder-shortcuts"><small class="u1-local-label">Recent local imports</small>${readyFiles().slice(0,3).map(file=>`<button type="button" data-file="${file.id}">${icon('files')}<span>${esc(file.name)}</span></button>`).join('')||'<p>Connect cloud access or import your own local files.</p>'}</div>${action('Files & storage','files')}`;}
  function weatherBody(){const data=state.weather;if(!data||!data.current)return `<div class="prism-weather-location">${esc(state.profile.city)}${action('Location','settings')}</div>${empty(weatherBusy?'Checking the forecast...':'Weather unavailable','Only matched, country-filtered weather observations are shown.')}`;const current=data.current,code=current.weather_code;const glyph=code<2?(current.is_day?'sun':'moon'):code<50?'cloud':'rain';const label=code===0?'Clear':code<=3?'Partly cloudy':code<50?'Foggy':code<70?'Rain':code<80?'Snow':'Showers';return `<div class="prism-weather-location"><strong>${esc(data.city)}, ${esc(data.region==='Victoria'?'VIC':data.region)}</strong><button type="button" class="prism-icon-button" data-route="settings" aria-label="Weather location settings">${icon('settings')}</button></div><div class="prism-weather-current">${icon(glyph)}<strong>${Math.round(current.temperature_2m)}<span>°C</span></strong></div><p class="prism-weather-detail">↑ ${Math.round(data.daily?.temperature_2m_max?.[0]??current.temperature_2m)}° <span>↓ ${Math.round(data.daily?.temperature_2m_min?.[0]??current.temperature_2m)}°</span> ${label}</p><div class="prism-mountain" aria-hidden="true"></div><span class="prism-weather-source">${data.stale?'Last known reading · ':''}${esc(data.source)} · ${esc(current.time.replace('T',' '))}</span>`;}
  function todayBody(){const today=dayKey();const events=items('event').filter(event=>dayKey(new Date(event.payload.start))===today).sort((a,b)=>a.payload.start.localeCompare(b.payload.start));const tasks=items('task').filter(task=>!task.payload.done&&task.payload.due===today);if(!events.length&&!tasks.length)return `<div class="prism-today-empty">${icon('calendar')}<strong>A little room in your day.</strong><p>No local events or due tasks today. Google Calendar access is not connected here.</p>${newButton('event','Add an event')}</div>`;return `<div class="prism-agenda">${events.slice(0,4).map(event=>`<button type="button" data-edit="${event.id}">${icon('calendar')}<span>${esc(event.title)}</span><time>${timeLabel(event.payload.start,{hour:'numeric',minute:'2-digit'})}</time></button>`).join('')}${tasks.slice(0,3).map(task=>`<button type="button" data-edit="${task.id}">${icon('tasks')}<span>${esc(task.title)}</span><small>Due today</small></button>`).join('')}</div><p class="prism-source">Local calendar and tasks · no cloud events assumed</p>`;}
  function integrationRows(){return `<div class="prism-integration-rows">${[['google_drive','Google Drive'],['codex','Codex'],['claude','Claude'],['canva','Canva'],['antigravity','Antigravity'],['github','GitHub'],['google_calendar','Google Calendar'],['gmail','Gmail']].map(([id,name])=>{const status=providerStatus(id);return `<button type="button" data-integration="${id}">${badge(id)}<span>${name}</span>${statusTag(status.text,status.style)}</button>`;}).join('')}</div>`;}
  function home(){return `<div class="prism-home-layout"><div class="prism-home-center"><section class="prism-hero"><div class="prism-hero-copy"><p id="prism-date"></p><div class="prism-clock"><strong id="prism-time"></strong><span id="prism-period"></span></div><h1 id="prism-greeting"></h1><p class="prism-hero-subtitle">Big ideas. Real progress.</p><div class="prism-quote">“Discipline today,<br>freedom tomorrow.”<i></i></div></div><div class="prism-planet" aria-label="Decorative rotating Earth"><canvas id="prism-globe" aria-hidden="true"></canvas><span class="prism-orbit orbit-one"></span><span class="prism-orbit orbit-two"></span><span class="prism-globe-credit">EARTH / NASA · ARCHIVED IMAGERY</span></div><div class="prism-hero-words" aria-hidden="true">IDEAS<br>PROJECTS<br>AI<br>AUTOMATION<br>FREEDOM</div><div class="prism-horizon" aria-hidden="true"></div></section>${providerCards()}<div class="prism-dashboard-panels">${panel('Projects',`<div id="prism-home-projects">${projectRows()}</div>`,action('See all','projects'),'projects')}${panel('System status',`<div id="prism-home-system">${systemBody()}</div>`,action('Details','system'),'system')}${panel('Drive & storage',driveBody(),action('Browse','files'),'files')}</div><div class="prism-home-bottom">${panel('Your next moves',`<div class="prism-next-moves">${items('task').filter(task=>!task.payload.done).slice(0,3).map(task=>taskRow(task)).join('')||'<p>No open local tasks. Add what you want to move forward.</p>'}</div>`,newButton('task','Add task'),'tasks')}${panel('Create something real',`<p class="prism-card-copy">Planners, coloring pages, calendars and print-ready PDFs. Your Creative Studio is ready.</p>${action('Open Creative Studio','studio','primary')}`,'','media')}</div></div><aside class="prism-home-rail" aria-label="Daily overview"><section class="prism-panel prism-weather" id="prism-home-weather">${weatherBody()}</section>${panel('Today',`<div id="prism-home-today">${todayBody()}</div>`,action('Calendar','calendar'),'calendar')}${panel('Integrations',`<div id="prism-home-integrations">${integrationRows()}</div>`,action('Manage','integrations'),'integrations')}</aside></div>`;}
  function projectsView(){const projects=items('project');return header('TURN IDEAS INTO PROGRESS','Projects','Real workspace records. Progress percentages are entered by you, never invented.',newButton('project','New project'))+`<div class="prism-project-board">${projects.map(project=>`<article class="prism-panel prism-project-card"><header><span class="prism-row-icon">${icon('projects')}</span>${statusTag(project.payload.status,project.payload.status==='done'?'success':'neutral')}</header><small>${esc(project.payload.category)}</small><h2>${esc(project.title)}</h2><p>${esc(project.payload.notes||'Add a brief, a next step, or a useful link.')}</p><div class="prism-project-progress">${Number.isFinite(project.payload.progress)?`<progress max="100" value="${project.payload.progress}"></progress><span>${project.payload.progress}% <small>user-reported</small></span>`:'<span>Progress not tracked</span>'}</div><footer><span>${timeLabel(project.updated)}</span><button type="button" class="prism-button quiet" data-edit="${project.id}">Open ${icon('arrow')}</button></footer></article>`).join('')||empty('Start with something that matters.','Your project board is empty. Existing local folders are shown below, without invented progress.',newButton('project','Create a project'))}</div>`+panel('Existing local folders',`<p class="prism-source">Read-only directory metadata beside this workspace. Folder modification time is not a measure of project progress.</p><div class="prism-folder-grid">${state.folders.map((folder,index)=>`<button type="button" data-folder="${index}">${icon('projects')}<span><strong>${esc(folder.name)}</strong><small>Modified ${timeLabel(folder.modified)}</small></span>${icon('arrow')}</button>`).join('')||'<p class="prism-card-copy">No neighboring folders are available.</p>'}</div>`,'','projects');}
  function taskRow(task){return `<div class="prism-task-row"><label><input type="checkbox" data-task="${task.id}" ${task.payload.done?'checked':''}><span class="prism-check-box">${icon('check')}</span><span class="${task.payload.done?'is-done':''}">${esc(task.title)}</span></label><span class="prism-task-due ${task.payload.due&&task.payload.due<dayKey()&&!task.payload.done?'overdue':''}">${esc(task.payload.due||'No due date')}</span><button type="button" class="prism-icon-button" data-edit="${task.id}" aria-label="Edit ${esc(task.title)}">${icon('notes')}</button></div>`;}
  function tasksView(){const tasks=items('task').filter(task=>taskFilter==='all'||(taskFilter==='done'?task.payload.done:!task.payload.done));return header('MAKE ROOM FOR THE IMPORTANT THINGS','Tasks','A real, local task list with dates, priorities and recoverable deletion.',newButton('task','New task'))+`<div class="prism-tabs">${[['all','All tasks'],['open','In progress'],['done','Completed']].map(([value,label])=>`<button type="button" data-task-filter="${value}" class="${taskFilter===value?'active':''}">${label}</button>`).join('')}</div>`+panel('Your task list',tasks.map(taskRow).join('')||empty('Nothing on this list yet.','Create a task and set its next step. No sample tasks are added.'),'','tasks');}
  function notesView(){return header('CAPTURE THE THOUGHT. KEEP THE MOMENT.','Notes','Your writing stays in the local workspace database. It is not encrypted.',newButton('note','New note'))+`<div class="prism-note-grid">${items('note').map(note=>`<button type="button" class="prism-panel prism-note-card" data-edit="${note.id}"><span>${esc(note.payload.tag||'PERSONAL NOTE')}</span><h2>${esc(note.title)}</h2><p>${esc(note.payload.text||'An empty page, ready for your next thought.')}</p><small>Updated ${timeLabel(note.updated)}</small></button>`).join('')||empty('A place for your next good idea.','Add notes, project briefs, lists and thoughts.',newButton('note','Write a note'))}</div>`;}
  function filesView(mediaOnly=false){const list=readyFiles().filter(file=>(!mediaOnly||/^(image|video|audio)\//.test(file.mime))&&`${file.name} ${file.folder}`.toLowerCase().includes(fileFilter.toLowerCase()));return header(mediaOnly?'YOUR CREATIVE LIBRARY':'A PLACE FOR WHAT MATTERS',mediaOnly?'Media':'Files & Drive',mediaOnly?'Imported images, audio and video. No media is scraped or downloaded from private accounts.':'Local imports are real files, stored separately from application code and provider secrets.',`<button type="button" class="prism-button primary" data-upload>${icon('upload')}Import files</button>`)+(mediaOnly?`<div class="prism-inline-actions">${action('Document & PDF Studio','studio','primary')}${action('Existing video tools','legacy:studio')}${action('All files','files')}</div>`:`<div class="prism-storage-grid">${panel('Google Drive',driveBody(),'<button type="button" class="prism-button quiet" data-integration="google_drive">Connection details</button>','files')}${panel('Local U1 files',`<div class="prism-storage-number">${bytes(state.storage?.used||0)}<span>Imported into this workspace</span></div><p class="prism-card-copy">Up to 25 MB per file, with a 1 GB local import allowance. Items in Trash retain their file contents.</p><p class="prism-source">This is not your Google Drive usage or the total disk capacity.</p>`,'','system')}</div>`)+`<div class="prism-list-toolbar"><label>${icon('search')}<input type="search" id="prism-file-filter" placeholder="Search imported filenames and folders" value="${esc(fileFilter)}"></label><span>${list.length} ${list.length===1?'file':'files'}</span></div><div id="prism-upload-progress" role="status" hidden></div><div class="prism-file-table">${list.length?`<div class="prism-file-table-head"><span>NAME</span><span>FOLDER</span><span>SIZE</span><span>IMPORTED</span></div>${list.map(file=>`<button type="button" class="prism-file-row" data-file="${file.id}"><span>${icon(file.mime.startsWith('image/')||file.mime.startsWith('video/')?'media':'files')}<strong>${esc(file.name)}</strong></span><span>${esc(file.folder)}</span><span>${bytes(file.size)}</span><span>${timeLabel(file.created,{day:'numeric',month:'short'})}</span></button>`).join('')}`:empty('Your files belong here.','Import your own files to browse, search, preview supported media, and download them. Cloud folders remain unavailable until authorized.','<button type="button" class="prism-button primary" data-upload>Import a file</button>')}</div>`;}
  function integrationView(){const known=[['google_drive','Google Drive','Primary cloud storage'],['codex','ChatGPT / Codex','CLI account telemetry and coding tools'],['claude','Claude','Analysis, planning and writing'],['canva','Canva','Design and document handoff'],['antigravity','Antigravity','Your existing development environment'],['github','GitHub','Repository management'],['slack','Slack','Team communication'],['google_calendar','Google Calendar','Calendar authorization'],['gmail','Gmail / Email','Email tools and authorization'],['notion','Notion','Knowledge workspace']];const seen=new Set(known.map(([id])=>id));const additional=state.catalog.filter(card=>!seen.has(card.id)&&!['anthropic','openai'].includes(card.id)).map(card=>[card.id,card.name,card.note||card.category]);return header('YOUR TOOLS. ONE CLEAR PICTURE.','Integrations','Configured settings are not proof of authentication. Only verified readers are labeled as readable.',action('Manage saved credentials','connections','primary'))+`<div class="prism-integrations-grid">${[...known,...additional].map(([id,name,description])=>{const status=providerStatus(id);return `<article class="prism-panel prism-integration-card"><header>${badge(id)}${statusTag(status.text,status.style)}</header><h2>${esc(name)}</h2><p>${esc(description)}</p><button type="button" class="prism-button quiet" data-integration="${esc(id)}">Connection details ${icon('arrow')}</button></article>`;}).join('')}</div>`;}
  function calendarView(){const first=new Date(`${month}-01T12:00:00`),offset=(first.getDay()+6)%7,days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate();const events=items('event');return header('YOUR TIME, WITH INTENTION','Calendar','Local events are stored on this Mac. Google Calendar events are not fabricated or imported without authorization.',newButton('event','New event'))+`<div class="prism-calendar-toolbar"><button type="button" class="prism-icon-button" data-month="-1" aria-label="Previous month">‹</button><h2>${esc(first.toLocaleDateString('en-AU',{month:'long',year:'numeric'}))}</h2><button type="button" class="prism-icon-button" data-month="1" aria-label="Next month">›</button><button type="button" class="prism-button quiet" data-integration="google_calendar">Google Calendar setup</button></div><div class="prism-calendar-grid">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(day=>`<span class="prism-calendar-weekday">${day}</span>`).join('')}${Array.from({length:Math.ceil((days+offset)/7)*7},(_,index)=>{const day=index-offset+1;if(day<1||day>days)return '<div class="prism-calendar-day outside"></div>';const key=`${month}-${String(day).padStart(2,'0')}`,matches=events.filter(event=>dayKey(new Date(event.payload.start))===key);return `<div class="prism-calendar-day ${key===dayKey()?'today':''}"><button type="button" data-day="${key}" aria-label="Add event on ${key}">${day}</button>${matches.slice(0,3).map(event=>`<button type="button" class="prism-calendar-event" data-edit="${event.id}">${esc(event.title)}</button>`).join('')}${matches.length>3?`<small>+${matches.length-3} more</small>`:''}</div>`;}).join('')}</div><div class="prism-upcoming-events">${panel('Upcoming local events',events.filter(event=>new Date(event.payload.start).getTime()>=Date.now()-86400000).sort((a,b)=>a.payload.start.localeCompare(b.payload.start)).slice(0,12).map(event=>`<button type="button" class="prism-agenda-row" data-edit="${event.id}">${icon('calendar')}<strong>${esc(event.title)}</strong><time>${timeLabel(event.payload.start)}</time></button>`).join('')||empty('No upcoming local events.','Add an appointment or configure your calendar connection.'),'','calendar')}</div>`;}
  function aiView(){return header('A LITTLE CLARITY. A LOT OF POSSIBILITY.','AI Command','Route natural-language requests to real local actions, then hand off deeper work to your existing AI tools.')+`<section class="prism-command-surface"><div class="prism-command-emblem">${mark()}</div><h2>What would you like to move forward?</h2><p>Local commands take action. Provider prompts are prepared for review in your existing assistant, not silently sent or billed.</p><form id="prism-command-form"><label class="prism-command-box"><textarea id="prism-command-input" rows="3" maxlength="12000" placeholder="Show today's schedule. Find a proposal. Create a project. Ask Claude to analyse an idea..." aria-label="AI command" required></textarea><button type="submit" class="prism-button primary">Run command ${icon('arrow')}</button></label></form><div class="prism-command-suggestions">${["Show today's schedule","Create a new project","Show system performance","Find my files"].map(command=>`<button type="button" data-command="${esc(command)}">${esc(command)}</button>`).join('')}</div><p id="prism-command-result" role="status"></p></section>${providerCards()}<div class="prism-inline-actions">${action('Open existing AI assistant','legacy:assistant')}${action('Prompt builder','studio')}${action('Account connections','integrations')}</div>`;}
  function systemView(){return header('CLEAR SIGNALS. NO INVENTED NUMBERS.','System','Measured locally where a supported reader exists. GPU and temperature values remain unavailable.')+`<div class="prism-system-layout">${panel('Live machine telemetry',`<div id="prism-system-details">${systemBody()}</div>`,statusTag('Local readings','success'),'system')}${panel('Machine & network',`<div id="prism-network-details">${networkBody()}</div>`,'','globe')}</div>`+panel('Your existing system tools',appCards(extras.filter(([id])=>['tools','osint','sports','finance','crypto','deploy','gaming','settings'].includes(id))),'','system');}
  function networkBody(){const data=state.system;return `<dl class="prism-detail-list"><div><dt>Platform</dt><dd>${esc(data?.platform||'Unavailable')} ${esc(data?.architecture||'')}</dd></div><div><dt>Available disk</dt><dd>${bytes(data?.disk?.free)}</dd></div><div><dt>Available memory</dt><dd>${bytes(data?.memory?.available)}</dd></div><div><dt>Network receive</dt><dd>${Number.isFinite(data?.network?.receive_rate)?`${bytes(data.network.receive_rate)}/s`:'Collecting sample'}</dd></div><div><dt>Network send</dt><dd>${Number.isFinite(data?.network?.send_rate)?`${bytes(data.network.send_rate)}/s`:'Collecting sample'}</dd></div><div><dt>GPU / temperature</dt><dd>Unavailable</dd></div></dl><p class="prism-source">${esc(data?.notice||'Waiting for a local telemetry response.')}</p>`;}
  function automationView(){return header('LET ROUTINES MAKE ROOM FOR YOU.','Automation','Your existing automation and scheduler tools remain intact. No new paid background work is enabled automatically.')+`<div class="prism-two-columns">${panel('Auto Finder',`<div class="prism-feature-icon">${icon('automation')}</div><h3>A workspace that can notice the gaps.</h3><p class="prism-card-copy">The existing local advisor checks installation metadata and suggests improvements. It does not install software, spend subscription credits, or repair files without approval.</p>${action('Open Auto Finder','legacy:finder','primary')}`,'','automation')}${panel('Schedules & briefings',`<div class="prism-feature-icon">${icon('calendar')}</div><h3>Manage the routines you already have.</h3><p class="prism-card-copy">Open the existing scheduler and system settings to review supported jobs. Gmail PDF retrieval and automatic cloud briefings are not represented as connected here.</p>${action('Scheduler & system settings','legacy:settings')}${action('Email workspace','legacy:comms')}`,'','calendar')}</div>`;}
  function settingsView(){const profile=state.profile;return header('MAKE THIS SPACE YOURS.','Settings','Profile, visual effects and local workspace preferences. Existing security and integration settings are preserved.')+`<div class="prism-settings-grid">${panel('Profile & location',`<form id="prism-profile-form" class="prism-form"><label>Your name<input name="name" maxlength="70" value="${esc(profile.name)}" required></label><div class="prism-form-row"><label>Weather location<input name="city" maxlength="120" value="${esc(profile.city)}" required></label><label>Country code<input name="country" maxlength="2" value="${esc(profile.country)}" required></label></div><label>Time zone<input name="timezone" value="${esc(profile.timezone)}" required></label><label>Visual effects<select name="effects">${['reduced','balanced','maximum'].map(value=>`<option value="${value}" ${profile.effects===value?'selected':''}>${value[0].toUpperCase()+value.slice(1)}</option>`).join('')}</select></label><label class="prism-checkbox"><input name="focus" type="checkbox" ${profile.focus?'checked':''}>Focus mode: simplify the dashboard</label><label class="prism-checkbox"><input name="contrast" type="checkbox" ${profile.contrast?'checked':''}>Higher contrast panels</label><p class="prism-source">System reduced-motion settings take precedence. Balanced globe motion is capped to reduce GPU work; Maximum allows a higher frame cap.</p><button type="submit" class="prism-button primary">Save preferences</button></form>`,'','user')}${panel('Privacy, accounts & recovery',`<div class="prism-settings-actions">${action('AI providers & integrations','integrations')}${action('Google Drive & files','files')}${action('Security & notifications','legacy:settings')}<button type="button" class="prism-button quiet" data-backup>${icon('download')}Export workspace backup</button><button type="button" class="prism-button quiet" data-trash-view>${icon('restore')}Open Trash & restore</button></div><p class="prism-card-copy">U1 records and imported files are stored locally, outside application source. They are not encrypted. Backups exclude provider credentials and file contents.</p><div class="prism-about"><span class="prism-logo">${mark()}</span><h3>U1 OS</h3><p>Your world. Amplified.</p><small>A visual and productivity layer around your existing U1 workspace. Provider marks are stylized identifiers, not endorsements.</small><a href="https://commons.wikimedia.org/wiki/File:Land_ocean_ice_2048.jpg" target="_blank" rel="noopener noreferrer">Earth imagery: NASA/GSFC, via Wikimedia</a><a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">Earth image license: CC BY-SA 3.0</a></div>`,'','shield')}</div>`;}
  function appCards(list){return `<div class="prism-app-grid">${list.map(([id,name,glyph])=>`<button type="button" data-route="legacy:${id}">${icon(glyph)}<strong>${esc(name)}</strong><span>Open existing workspace ${icon('arrow')}</span></button>`).join('')}</div>`;}
  const baseAutomationView=automationView;
  automationView=()=>header('YOUR WORKSPACE, IN MOTION','Automation','Safe local routines run automatically while your U1 server is running. External actions stay approval-gated.')+autopilotView(autopilot)+`<div class="u1-existing-automation">${action('Existing advisor','legacy:finder')}${action('Advanced schedules','legacy:settings')}${action('Email workspace','legacy:comms')}</div>`;
  async function refreshAutopilot(){try{autopilot=await api(endpoint('autopilot'));if(state.view==='automation'&&!modal.open)render();}catch(_){autopilot=null;}}
  shell.addEventListener('click',async event=>{const button=event.target.closest('[data-autopilot-key]');if(!button)return;button.disabled=true;try{autopilot=await api(endpoint('autopilot'),{settings:{[button.dataset.autopilotKey]:button.dataset.autopilotValue==='true'}});render();notice('Local autopilot preferences saved.');}catch(error){notice(safeError(error),true);}finally{if(button.isConnected)button.disabled=false;}});
  function appsView(){return header('KEEP THE POWER. LOSE THE CLUTTER.','App library','Every existing specialist workspace remains available. Opening a tool does not imply its provider is configured.')+appCards(extras);}
  function render(){disposeGlobe();disposeGlobe=()=>{};if(state.view.startsWith('legacy:'))return;const views={home,ai:aiView,projects:projectsView,files:()=>filesView(false),integrations:integrationView,calendar:calendarView,tasks:tasksView,notes:notesView,media:()=>filesView(true),automation:automationView,system:systemView,settings:settingsView,apps:appsView};page.innerHTML=(views[state.view]||home)();page.className=`prism-view prism-view-${state.view}`;if(state.view==='home'){updateClock();disposeGlobe=mountGlobe($('prism-globe'),state.profile.effects);}updateNav();}
  function updateNav(){shell.querySelectorAll('.prism-sidebar [data-route]').forEach(button=>{const active=button.dataset.route===state.view;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});shell.querySelectorAll('[data-count]').forEach(el=>{const count=el.dataset.count==='tasks'?items('task').filter(task=>!task.payload.done).length:el.dataset.count==='projects'?items('project').length:0;el.textContent=count?String(count):'';});$('prism-connection-label').textContent=state.connected?'LOCAL WORKSPACE ONLINE':state.loaded?'LOCAL SERVER UNAVAILABLE':'CONNECTING TO LOCAL WORKSPACE';$('prism-connection-label').classList.toggle('offline',!state.connected);}
  function route(value,options={}){if(value==='studio'){location.href='/studio.html';return;}if(value==='connections'){location.href='/integrations.html';return;}if(value==='web'){webDialog();return;}if(value==='home'||NAV.some(([id])=>id===value)||value==='apps'||value.startsWith('legacy:'))state.view=value;else state.view='home';shell.classList.remove('nav-open');$('prism-menu').setAttribute('aria-expanded','false');page.hidden=state.view.startsWith('legacy:');$('prism-legacy').hidden=!page.hidden;if(page.hidden){disposeGlobe();const id=state.view.slice(7),button=document.getElementById(`nav-${id}`);if(id==='studio'){if(typeof CommandCenter!=='undefined')CommandCenter.switchSection('studio');}else if(button)button.click();else notice('That existing workspace is unavailable.',true);updateNav();}else render();if(!options.history)historyReplace(state.view);document.title=`${NAV.find(([id])=>id===state.view)?.[1]||extras.find(([id])=>`legacy:${id}`===state.view)?.[1]||'App library'} | U1 OS`;$('prism-scroll').scrollTop=0;}
  function historyReplace(value){window.history.replaceState(null,'',`#${encodeURIComponent(value)}`);}
  function updateClock(){if(state.view!=='home')return;const now=new Date(),parts=new Intl.DateTimeFormat('en-AU',{timeZone:state.profile.timezone,hour:'2-digit',minute:'2-digit',hour12:true}).formatToParts(now);if($('prism-time'))$('prism-time').textContent=parts.filter(part=>['hour','literal','minute'].includes(part.type)).map(part=>part.value).join('').trim();if($('prism-period'))$('prism-period').textContent=(parts.find(part=>part.type==='dayPeriod')?.value||'').toUpperCase();if($('prism-date'))$('prism-date').textContent=now.toLocaleDateString('en-AU',{timeZone:state.profile.timezone,weekday:'short',day:'numeric',month:'short',year:'numeric'}).toUpperCase();const hour=Number(new Intl.DateTimeFormat('en-AU',{timeZone:state.profile.timezone,hour:'numeric',hourCycle:'h23'}).format(now));if($('prism-greeting'))$('prism-greeting').textContent=`Good ${hour<12?'morning':hour<18?'afternoon':'evening'}, ${state.profile.name}`;}
  async function refreshSummary(){if(summaryBusy)return;summaryBusy=true;try{const data=await api(endpoint('summary'));state={...state,records:data.records||[],files:data.files||[],folders:data.folders||[],storage:data.storage,profile:{...state.profile,...data.profile},connected:true,loaded:true};applyPreferences();if(!modal.open&&!searchDialog.open&&!pendingUploads)render();else updateNav();}catch(error){state.connected=false;state.loaded=true;updateNav();if(!state.records.length&&!modal.open)render();console.warn('U1 workspace connection unavailable');}finally{summaryBusy=false;}}
  async function refreshSystem(){if(systemBusy)return;systemBusy=true;try{state.system=await api(endpoint('system'));if(history.at(-1)?.at!==state.system.sampled_at)history=[...history,{at:state.system.sampled_at,cpu:state.system.cpu}].slice(-30);for(const id of ['prism-home-system','prism-system-details'])if($(id))$(id).innerHTML=systemBody();if($('prism-network-details'))$('prism-network-details').innerHTML=networkBody();}catch(_){state.system=null;for(const id of ['prism-home-system','prism-system-details'])if($(id))$(id).innerHTML=systemBody();}finally{systemBusy=false;}}
  async function refreshWeather(){if(weatherBusy)return;weatherBusy=true;try{state.weather=await api(endpoint('weather')+`?city=${encodeURIComponent(state.profile.city)}&country=${encodeURIComponent(state.profile.country)}`);}catch(_){if(state.weather)state.weather={...state.weather,stale:true};}finally{weatherBusy=false;if($('prism-home-weather'))$('prism-home-weather').innerHTML=weatherBody();}}
  async function refreshUsage(){try{state.usage=await api('/api/workspace/usage');if($('prism-home-integrations'))$('prism-home-integrations').innerHTML=integrationRows();}catch(_){state.usage=null;}}
  async function refreshNotifications(){try{const data=await api('/api/workspace/notifications');state.notifications=Array.isArray(data)?data:Array.isArray(data.notifications)?data.notifications:Array.isArray(data.items)?data.items:[];}catch(_){state.notifications=[];}const count=state.notifications.length;$('prism-notification-count').hidden=!count;$('prism-notification-count').textContent=String(count);}
  function openModal(title,body,eyebrow='U1 WORKSPACE'){returnFocus=document.activeElement;$('prism-modal-title').textContent=title;$('prism-modal-eyebrow').textContent=eyebrow;$('prism-modal-content').innerHTML=body;modalSubmit=null;if(!modal.open)modal.showModal();const field=modal.querySelector('input:not([type="hidden"]),textarea,select');if(field)field.focus();}
  function closeModal(){modal.close();if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}if(returnFocus?.isConnected)returnFocus.focus();}
  function field(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
  function select(label,name,values,value){return `<label>${label}<select name="${name}">${values.map(item=>`<option value="${item}" ${item===value?'selected':''}>${item[0].toUpperCase()+item.slice(1)}</option>`).join('')}</select></label>`;}
  function localInputDate(value){if(!value)return '';const date=new Date(value);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}
  function editRecord(kind,record=null,preset={}){const item=record||{title:preset.title||'',payload:preset.payload||{}},value=item.payload;let fields=field('Title','title',item.title,'text','maxlength="160" required');if(kind==='project'){fields+=`<div class="prism-form-row">${field('Category','category',value.category||'Personal','text','maxlength="80"')}${select('Status','status',['planned','active','paused','done'],value.status||'planned')}</div>${field('Progress (%) - leave blank if not measured','progress',Number.isFinite(value.progress)?value.progress:'','number','min="0" max="100"')}${field('Project link (optional)','url',value.url||'','url')}<label>Project notes<textarea name="notes" rows="5" maxlength="12000">${esc(value.notes||'')}</textarea></label>`;}else if(kind==='task'){fields+=`<div class="prism-form-row">${field('Due date','due',value.due||'','date')}${select('Priority','priority',['low','normal','high'],value.priority||'normal')}</div><label class="prism-checkbox"><input type="checkbox" name="done" ${value.done?'checked':''}>Completed</label><label>Notes<textarea name="notes" rows="5" maxlength="8000">${esc(value.notes||'')}</textarea></label>`;}else if(kind==='note'){fields+=`${field('Tag','tag',value.tag||'','text','maxlength="70"')}<label>Your note<textarea name="text" rows="12" maxlength="16000">${esc(value.text||'')}</textarea></label>`;}else{const start=value.start||`${dayKey()}T09:00`;fields+=`<div class="prism-form-row">${field('Starts (device local time)','start',localInputDate(start),'datetime-local','required')}${field('Ends (optional)','end',localInputDate(value.end),'datetime-local')}</div>${field('Location','location',value.location||'','text','maxlength="200"')}<label>Notes<textarea name="notes" rows="4" maxlength="8000">${esc(value.notes||'')}</textarea></label><p class="prism-source">This creates a local calendar event, not a Google Calendar invitation.</p>`;}openModal(`${record?'Edit':'New'} ${kind}`,`<form id="prism-record-form" class="prism-form">${fields}<p id="prism-form-error" class="prism-form-error" role="alert"></p><footer>${record?`<button type="button" class="prism-button danger" data-trash="${record.id}" data-kind="${kind}">${icon('trash')}Move to Trash</button>`:''}<button type="submit" class="prism-button primary">${icon('check')}Save ${kind}</button></footer></form>`);modalSubmit=async form=>{const data=Object.fromEntries(new FormData(form));let payload;if(kind==='project')payload={...data,progress:data.progress===''?null:Number(data.progress)};else if(kind==='task')payload={...data,done:form.elements.done.checked,project:value.project||''};else if(kind==='event')payload={...data,start:new Date(data.start).toISOString(),end:data.end?new Date(data.end).toISOString():''};else payload=data;await api(endpoint('record'),{id:record?.id,kind,title:data.title,payload,expected_updated:record?.updated});closeModal();await refreshSummary();notice(`${kind[0].toUpperCase()+kind.slice(1)} saved in your local workspace.`);};}
  function integrationDetails(id){const card=state.catalog.find(card=>card.id===(id==='claude'?'anthropic':id)),name=providers.find(([key])=>key===id)?.[1]||({google_drive:'Google Drive',google_calendar:'Google Calendar',gmail:'Gmail',github:'GitHub',slack:'Slack',notion:'Notion'}[id])||card?.name||id;const status=providerStatus(id);const portals={google_drive:'https://drive.google.com/',google_calendar:'https://calendar.google.com/',gmail:'https://mail.google.com/',canva:'https://www.canva.com/',github:'https://github.com/',slack:'https://slack.com/',notion:'https://www.notion.so/'};openModal(name,`<div class="prism-connection-detail">${badge(id)}${statusTag(status.text,status.style)}<h3>Keep connection status honest.</h3><p>${id==='codex'?'The local Codex usage reader can report account limits when its CLI session is available. That does not grant every other provider API access.':id==='google_drive'?'Your reported Drive plan is 5 TB. U1 has no verified Drive OAuth file or quota reader, so files, usage and available capacity are not invented.':esc(card?.note||'No verified account authorization has been established in this workspace.')}</p><p>Signing in to a provider in another browser tab does not authorize this local app. Existing saved credentials remain in the original connection manager.</p><div class="prism-inline-actions">${action('Manage connection settings','connections','primary')}${id==='codex'||id==='claude'?action('Open existing assistant','legacy:assistant'):''}${portals[id]?`<a class="prism-button quiet" href="${portals[id]}" target="_blank" rel="noopener noreferrer">Open ${esc(name)} ${icon('external')}</a>`:''}</div><small>Disconnect and test actions are available only through supported account-management flows. This panel does not fabricate an OAuth connection.</small></div>`,'ACCOUNT ACCESS');}
  async function providerAction(id,prompt=''){if(id==='canva'){if(prompt){route('studio');return;}integrationDetails(id);return;}if(id==='antigravity'){route('legacy:tools');notice('Opened your existing tool workspace. Antigravity account access is not assumed.');return;}route('legacy:assistant');const area=document.querySelector('#section-assistant textarea');if(area&&prompt){area.value=prompt;area.dispatchEvent(new Event('input',{bubbles:true}));}const select=document.querySelector('#section-assistant select');if(select){const option=Array.from(select.options).find(option=>option.value.toLowerCase().includes(id));if(option){select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));}}notice(prompt?'Your prompt is prepared. Review it in the assistant before running the provider.':'Opened the existing assistant. Provider authorization is checked when used.');}
  function searchCatalog(){const results=NAV.map(([id,title,glyph])=>({title,description:'Workspace page',glyph,run:()=>route(id)}));results.push({title:'Creative Studio',description:'PDFs, planners, coloring pages and prompts',glyph:'media',run:()=>route('studio')},{title:'App library',description:'All existing specialist tools',glyph:'integrations',run:()=>route('apps')});for(const record of state.records)results.push({title:record.title,description:`${record.kind} · ${record.payload.tag||record.payload.category||''}`,keywords:JSON.stringify(record.payload),glyph:record.kind==='project'?'projects':record.kind==='task'?'tasks':record.kind==='event'?'calendar':'notes',run:()=>editRecord(record.kind,record)});for(const file of readyFiles())results.push({title:file.name,description:`Imported file · ${file.folder}`,glyph:'files',run:()=>fileDetails(file.id)});for(const [id,title]of providers)results.push({title,description:'AI / creative provider',glyph:'ai',run:()=>providerAction(id)});return results;}
  function renderSearch(){const query=searchInput.value.toLowerCase().trim();searchItems=searchCatalog().filter(item=>`${item.title} ${item.description} ${item.keywords||''}`.toLowerCase().includes(query)).slice(0,24);searchSelection=Math.min(searchSelection,Math.max(0,searchItems.length-1));$('prism-search-results').innerHTML=searchItems.map((item,index)=>`<li><button type="button" data-search-index="${index}" class="${index===searchSelection?'selected':''}">${icon(item.glyph)}<span><strong>${esc(item.title)}</strong><small>${esc(item.description)}</small></span>${icon('arrow')}</button></li>`).join('')||'<li class="prism-search-empty">No local results. Cloud contents are not searched until a supported account connection exists.</li>';}
  function openSearch(query=''){returnFocus=document.activeElement;searchInput.value=query;searchSelection=0;renderSearch();if(!searchDialog.open)searchDialog.showModal();searchInput.focus();}
  function chooseSearch(index){const result=searchItems[index];if(!result)return;searchDialog.close();result.run();}
  function webDialog(){openModal('Open the web',`<form id="prism-web-form" class="prism-form"><label>Website address<input name="url" type="url" placeholder="https://example.com" required></label><p class="prism-source">Opens an ordinary website in your browser. This does not connect the website to U1.</p><button type="submit" class="prism-button primary">Open website ${icon('external')}</button></form>`);modalSubmit=form=>{const url=new URL(form.elements.url.value);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw new Error('Use an HTTP or HTTPS website without embedded credentials.');window.open(url.href,'_blank','noopener,noreferrer');closeModal();};}
  function runCommand(command){const text=command.trim(),lower=text.toLowerCase();if(!text)return;if(/\b(new|create|add)\b.*\bproject\b/.test(lower)){editRecord('project');return;}if(/\b(new|create|add)\b.*\btask\b/.test(lower)){editRecord('task');return;}if(/\b(new|create|add|write)\b.*\bnote\b/.test(lower)){editRecord('note');return;}if(/\b(schedule|calendar|appointment|today)\b/.test(lower)){route('calendar');return;}if(/\b(system|performance|cpu|memory|disk)\b/.test(lower)){route('system');return;}if(lower.includes('claude')){providerAction('claude',text);return;}if(lower.includes('codex')||lower.includes('chatgpt')){providerAction('codex',text);return;}if(lower.includes('canva')){integrationDetails('canva');return;}if(lower.includes('drive')){route('files');notice('Showing local file tools. Google Drive account access still needs setup.');return;}const project=items('project').find(project=>lower.includes(project.title.toLowerCase()));if(project){editRecord('project',project);return;}if(/\bfile/.test(lower)){fileFilter=lower.replace(/\b(find|show|my|the|latest|files?|related|to|me|all)\b/g,'').trim();route('files');return;}if(/\b(search|find|open)\b/.test(lower)){openSearch(text.replace(/^(find|search|open)\s+(my\s+)?/i,''));return;}$('prism-command-result').textContent='This request needs an AI provider rather than a local command. Choose Codex or Claude below to open the existing assistant; no paid request has been sent.';}
  function downloadBlob(blob,name){if(mediaUrl)URL.revokeObjectURL(mediaUrl);mediaUrl=URL.createObjectURL(blob);openModal('Your file is ready',`<div class="prism-download-card">${icon('download')}<h3>${esc(name)}</h3><p>Use the explicit save action below. Browser download settings determine where the file is saved.</p><a class="prism-button primary" href="${mediaUrl}" download="${esc(name)}">Save file ${icon('download')}</a></div>`);}
  async function fileDetails(id){const file=state.files.find(file=>file.id===id);if(!file)return;openModal(file.name,`<div class="prism-file-detail"><dl class="prism-detail-list"><div><dt>Folder</dt><dd>${esc(file.folder)}</dd></div><div><dt>Size</dt><dd>${bytes(file.size)}</dd></div><div><dt>Type</dt><dd>${esc(file.mime)}</dd></div><div><dt>Imported</dt><dd>${timeLabel(file.created)}</dd></div></dl><p class="prism-source">Stored locally. SHA-256 recorded when the upload completed. No external account download or watermark removal is implied.</p><div class="prism-inline-actions"><button type="button" class="prism-button primary" data-download-file="${id}">Prepare download ${icon('download')}</button>${/^(image\/(png|jpeg|webp|gif)|audio\/|video\/)/.test(file.mime)?`<button type="button" class="prism-button quiet" data-preview-file="${id}">Preview media</button>`:''}<button type="button" class="prism-button danger" data-trash="${id}" data-kind="file">Move to Trash</button></div><div id="prism-media-preview"></div></div>`);}
  async function loadFile(id,preview=false){notice('Reading your local file...');const data=await api(endpoint('file')+`?id=${encodeURIComponent(id)}`);const binary=atob(data.content),chunks=[];for(let offset=0;offset<binary.length;offset+=8192){const segment=binary.slice(offset,offset+8192);chunks.push(Uint8Array.from(segment,c=>c.charCodeAt(0)));}const blob=new Blob(chunks,{type:data.mime||'application/octet-stream'});if(!preview){downloadBlob(blob,data.name);return;}const target=$('prism-media-preview');if(!target)return;if(mediaUrl)URL.revokeObjectURL(mediaUrl);mediaUrl=URL.createObjectURL(blob);let element;if(/^image\/(png|jpeg|webp|gif)$/.test(data.mime)){element=document.createElement('img');element.alt=data.name;}else if(data.mime.startsWith('audio/')){element=document.createElement('audio');element.controls=true;}else if(data.mime.startsWith('video/')){element=document.createElement('video');element.controls=true;}else throw new Error('This file format is available for download, not inline preview.');element.src=mediaUrl;target.replaceChildren(element);}
  async function importFiles(fileList){if(pendingUploads)return;const files=Array.from(fileList);if(!files.length)return;pendingUploads=true;let done=0;try{for(const file of files){if(file.size>25*1024*1024)throw new Error(`${file.name} exceeds the 25 MB local file limit.`);const start=await api(endpoint('upload-start'),{name:file.name,mime:file.type||'application/octet-stream',size:file.size,folder:/^(image|audio|video)\//.test(file.type)?'Media':'Files'});for(let offset=0;offset<Math.max(file.size,1);offset+=32768){const data=new Uint8Array(await file.slice(offset,offset+32768).arrayBuffer());let binary='';for(let index=0;index<data.length;index++)binary+=String.fromCharCode(data[index]);await api(endpoint('upload-chunk'),{id:start.id,offset,content:btoa(binary)});const progress=$('prism-upload-progress');if(progress){progress.hidden=false;progress.textContent=`Importing ${file.name}: ${Math.round(Math.min(file.size,offset+32768)/Math.max(file.size,1)*100)}%`;}}done++;}notice(`${done} ${done===1?'file':'files'} imported into your local workspace.`);}catch(error){notice(safeError(error),true);}finally{pendingUploads=false;$('prism-file-input').value='';await refreshSummary();}}
  async function openTrash(){const data=await api(endpoint('trash'));openModal('Trash & recovery',`<p class="prism-card-copy">Items are recoverable. File contents in Trash still occupy local storage.</p><div class="prism-trash-list">${[...data.records,...data.files.map(file=>({...file,title:file.name,kind:'file'}))].map(item=>`<div><span><strong>${esc(item.title)}</strong><small>${esc(item.kind)}</small></span><button type="button" class="prism-button quiet" data-restore="${item.id}" data-kind="${item.kind}">${icon('restore')}Restore</button></div>`).join('')||empty('Trash is empty.','Removed projects, tasks, notes, calendar events and files will appear here.')}</div>`);}
  shell.addEventListener('click',async event=>{const button=event.target.closest('button,a');if(!button)return;try{if(button.dataset.route){if(modal.open)closeModal();route(button.dataset.route);return;}if(button.dataset.new){editRecord(button.dataset.new);return;}if(button.dataset.edit){const record=state.records.find(item=>item.id===button.dataset.edit);if(record)editRecord(record.kind,record);return;}if(button.dataset.provider){await providerAction(button.dataset.provider);return;}if(button.dataset.integration){integrationDetails(button.dataset.integration);return;}if(button.dataset.folder!==undefined){const folder=state.folders[Number(button.dataset.folder)];openModal(folder.name,`<div class="prism-connection-detail"><span class="prism-feature-icon">${icon('projects')}</span><p>This folder exists beside the current workspace. No progress, category or project health has been inferred from its name.</p><p>Folder modified: ${timeLabel(folder.modified)}</p><button type="button" class="prism-button primary" data-register-folder="${button.dataset.folder}">Create a project record for this folder</button></div>`);return;}if(button.dataset.registerFolder!==undefined){const folder=state.folders[Number(button.dataset.registerFolder)];editRecord('project',null,{title:folder.name});return;}if(button.dataset.file){await fileDetails(button.dataset.file);return;}if(button.dataset.downloadFile){await loadFile(button.dataset.downloadFile);return;}if(button.dataset.previewFile){await loadFile(button.dataset.previewFile,true);return;}if(button.hasAttribute('data-upload')){$('prism-file-input').click();return;}if(button.dataset.taskFilter){taskFilter=button.dataset.taskFilter;render();return;}if(button.dataset.month){const date=new Date(`${month}-01T12:00:00`);date.setMonth(date.getMonth()+Number(button.dataset.month));month=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;render();return;}if(button.dataset.day){editRecord('event',null,{payload:{start:`${button.dataset.day}T09:00`}});return;}if(button.dataset.command){runCommand(button.dataset.command);return;}if(button.dataset.trash){await api(endpoint('trash'),{id:button.dataset.trash,kind:button.dataset.kind});closeModal();await refreshSummary();notice('Moved to Trash. Restore it from Settings at any time.');return;}if(button.dataset.restore){await api(endpoint('restore'),{id:button.dataset.restore,kind:button.dataset.kind});await refreshSummary();await openTrash();return;}if(button.hasAttribute('data-trash-view')){await openTrash();return;}if(button.hasAttribute('data-backup')){const data=await api(endpoint('export'));downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`prism-workspace-${dayKey()}.json`);return;}if(button.hasAttribute('data-close-modal')){closeModal();return;}if(button.hasAttribute('data-close-search')){searchDialog.close();return;}if(button.dataset.searchIndex!==undefined){chooseSearch(Number(button.dataset.searchIndex));return;}}catch(error){notice(safeError(error),true);}});
  shell.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(form.id==='prism-command-form'){runCommand($('prism-command-input').value);return;}const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{if(form.id==='prism-profile-form'){const profile=Object.fromEntries(new FormData(form));profile.focus=form.elements.focus.checked;profile.contrast=form.elements.contrast.checked;const result=await api(endpoint('profile'),{profile});state.profile=result.profile;applyPreferences();render();await refreshWeather();notice('Your U1 preferences are saved.');}else if(modalSubmit){await modalSubmit(form);}}catch(error){const target=$('prism-form-error');if(target)target.textContent=safeError(error);else notice(safeError(error),true);}finally{if(submit?.isConnected)submit.disabled=false;}});
  shell.addEventListener('change',async event=>{const input=event.target;if(input.dataset.task){const task=state.records.find(item=>item.id===input.dataset.task);if(!task)return;try{await api(endpoint('record'),{id:task.id,kind:'task',title:task.title,payload:{...task.payload,done:input.checked},expected_updated:task.updated});await refreshSummary();}catch(error){input.checked=!input.checked;notice(safeError(error),true);}}});
  let fileFilterTimer;shell.addEventListener('input',event=>{if(event.target.id==='prism-file-filter'){fileFilter=event.target.value;clearTimeout(fileFilterTimer);fileFilterTimer=setTimeout(()=>{const start=event.target.selectionStart;render();const input=$('prism-file-filter');input?.focus();try{input?.setSelectionRange(start,start);}catch(_){}},220);}});
  $('prism-file-input').addEventListener('change',event=>importFiles(event.target.files));
  $('prism-menu').addEventListener('click',()=>{const open=shell.classList.toggle('nav-open');$('prism-menu').setAttribute('aria-expanded',String(open));});
  $('prism-search-button').addEventListener('click',()=>openSearch());searchInput.addEventListener('input',()=>{searchSelection=0;renderSearch();});searchInput.addEventListener('keydown',event=>{if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();if(!searchItems.length)return;searchSelection=(searchSelection+(event.key==='ArrowDown'?1:-1)+searchItems.length)%searchItems.length;renderSearch();$('prism-search-results').querySelector('.selected')?.scrollIntoView({block:'nearest'});}else if(event.key==='Enter'){event.preventDefault();chooseSearch(searchSelection);}});
  $('prism-notifications').addEventListener('click',()=>openModal('Notifications',state.notifications.length?`<div class="prism-notification-list">${state.notifications.slice(0,30).map(item=>`<article><strong>${esc(item.title||item.summary||'Workspace notification')}</strong><p>${esc(item.message||item.detail||'')}</p></article>`).join('')}</div>`:empty('No notifications from the reader.','Existing usage alerts and live warning feeds remain available in the live bar. No sample notifications are added.')));
  window.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'&&!event.altKey){event.preventDefault();event.stopImmediatePropagation();if(searchDialog.open)searchDialog.close();else if(!modal.open)openSearch();}else if(event.key==='Escape'&&searchDialog.open){event.preventDefault();event.stopImmediatePropagation();searchDialog.close();}},true);
  searchDialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();});modal.addEventListener('close',()=>{if(mediaUrl){URL.revokeObjectURL(mediaUrl);mediaUrl=null;}});
  window.addEventListener('hashchange',()=>route(decodeURIComponent(location.hash.slice(1))||'home',{history:true}));
  applyPreferences();route(decodeURIComponent(location.hash.slice(1))||'home',{history:true});
  catalog().then(()=>{if(state.view==='integrations'||state.view==='home')render();}).catch(()=>{});
  refreshSummary().then(()=>refreshWeather());refreshSystem();refreshUsage();refreshNotifications();
  const clockTimer=setInterval(()=>{if(!document.hidden)updateClock();},1000);
  refreshAutopilot();const autopilotTimer=setInterval(()=>{if(!document.hidden)refreshAutopilot();},60000);window.addEventListener('pagehide',()=>clearInterval(autopilotTimer));
  const systemTimer=setInterval(()=>{if(!document.hidden&&['home','system'].includes(state.view))refreshSystem();},5000);
  const summaryTimer=setInterval(()=>{if(!document.hidden&&!modal.open&&!searchDialog.open&&!pendingUploads)refreshSummary();},60000);
  const providerTimer=setInterval(()=>{if(!document.hidden){refreshUsage();refreshNotifications();}},60000);
  const weatherTimer=setInterval(()=>{if(!document.hidden)refreshWeather();},600000);
  window.addEventListener('pagehide',()=>{disposeGlobe();[clockTimer,systemTimer,summaryTimer,providerTimer,weatherTimer].forEach(clearInterval);if(mediaUrl)URL.revokeObjectURL(mediaUrl);});
}

// In-shell evidence-first business agents.
import './u1-agent-centre.js';
